import sys


def main():
    text = sys.stdin.read()
    config, _, queries = text.partition("===\n")
    data = {}
    current_section = ""  # global section initially

    for line in config.splitlines():
        line = line.strip()
        if not line or line.startswith(";"):
            continue
        if line.startswith("["):
            section_name = line[1:-1].strip()
            current_section = section_name.lower()
            data.setdefault(current_section, {})
        elif "=" in line:
            key, value = line.split("=", 1)
            key = key.strip().lower()
            raw_value = value.strip()

            if raw_value.startswith('"'):
                # Quoted value: extract between quotes
                end_quote = raw_value.find('"', 1)
                if end_quote != -1:
                    value = raw_value[1 : end_quote]
                else:
                    value = ""
            else:
                # Parse comments: remove everything after first ; or # not following space
                comment_pos = raw_value.find(';')
                if comment_pos != -1:
                    value = raw_value[:comment_pos].rstrip()
                else:
                    comment_pos = raw_value.find('#')
                    if comment_pos != -1:
                        value = raw_value[:comment_pos].rstrip()

            data[current_section].setdefault(key, "")  # use empty string for missing keys
            data[current_section][key] = value

    for query_line in queries.splitlines():
        query_line = query_line.strip()
        if not query_line:
            continue
        parts = query_line.split(".", 1)
        if len(parts) != 2:
            print("NOT FOUND")
            continue
        section, key = parts

        section = section.lower()
        key = key.lower()

        value = data.get(section, {}).get(key, "NOT FOUND")
        print(value)


if __name__ == "__main__":
    main()
